import React from 'react';
import { isWebGLAvailable } from '../../utils/webglSupport';

// Renders a 3D scene only where it can run, and never lets it take the page
// down: without WebGL, or if the scene throws (context lost, driver error),
// it shows `fallback` instead.
class WebGLErrorBoundary extends React.Component {
    constructor(props) {
        super(props);
        this.state = { failed: false };
    }

    static getDerivedStateFromError() {
        return { failed: true };
    }

    componentDidCatch(error) {
        // eslint-disable-next-line no-console
        console.warn('3D view unavailable, showing the static version:', error && error.message);
    }

    render() {
        return this.state.failed ? this.props.fallback : this.props.children;
    }
}

const WebGLBoundary = ({ children, fallback = null }) => {
    if (!isWebGLAvailable()) return fallback;
    return <WebGLErrorBoundary fallback={fallback}>{children}</WebGLErrorBoundary>;
};

export default WebGLBoundary;
