import React, { useRef } from 'react';
import { useFrame } from '@react-three/fiber';
import { MeshStandardMaterial, DoubleSide } from 'three';

// Kaaba proportions and details based on your 2D design
const KaabaModel = () => {
  const kaabaRef = useRef();

  // Optional: slow rotation for effect
  useFrame(() => {
    if (kaabaRef.current) {
      kaabaRef.current.rotation.y += 0.003;
    }
  });

  // Kaaba dimensions
  const width = 2;
  const height = 2.5;
  const depth = 2;

  // Gold band (Hizam) - wraps all four sides at the top
  const bandThickness = 0.05;
  const bandHeight = 0.18;
  const bandY = height - bandHeight - 0.5; // Lower the band from the very top

  // Kiswah embroidery band (simple gold lines) - below the Hizam
  const embroideryBandY = bandY - 0.13;

  // Door (east side, left corner with padding)
  const doorPadding = 0.25; // Padding from the left (north) edge
  const doorWidth = 0.6;
  const doorHeight = 1.0;
  const doorY = height / 2 - 0.7;
  const doorX = -width / 2 + doorWidth / 2 + doorPadding; // Left side of east face

  // Black Stone (Hajar al-Aswad) - northeast corner (intersection of north and east walls)
  const stoneRadiusX = 0.14;
  const stoneRadiusY = 0.09;
  const stoneY = -0.9;
  // Place at the very left end of the east wall (northeast corner)
  const stoneX = -width / 2 - 0.021; // Slightly outside the Kaaba wall (north face)
  const stoneZ = depth / 2 + 0.021;  // Slightly outside the Kaaba wall (east face)

  return (
    <group ref={kaabaRef}>
      {/* Main Kaaba cube */}
      <mesh position={[0, height / 2, 0]}>
        <boxGeometry args={[width, height, depth]} />
        <meshStandardMaterial color="#111" />
      </mesh>
      {/* Gold band (Hizam) - four sides */}
      {/* Front (east) */}
      <mesh position={[0, bandY, depth / 2 + bandThickness / 2]}>
        <boxGeometry args={[width, bandHeight, bandThickness]} />
        <meshStandardMaterial color="#d4af37" />
      </mesh>
      {/* Back (west) */}
      <mesh position={[0, bandY, -depth / 2 - bandThickness / 2]}>
        <boxGeometry args={[width, bandHeight, bandThickness]} />
        <meshStandardMaterial color="#d4af37" />
      </mesh>
      {/* Left (north) */}
      <mesh position={[-width / 2 - bandThickness / 2, bandY, 0]}>
        <boxGeometry args={[bandThickness, bandHeight, depth]} />
        <meshStandardMaterial color="#d4af37" />
      </mesh>
      {/* Right (south) */}
      <mesh position={[width / 2 + bandThickness / 2, bandY, 0]}>
        <boxGeometry args={[bandThickness, bandHeight, depth]} />
        <meshStandardMaterial color="#d4af37" />
      </mesh>
      {/* Kiswah embroidery band (simple gold lines) - below the Hizam */}
      {/* Front (east) */}
      <mesh position={[0, embroideryBandY, depth / 2 + bandThickness / 2 + 0.01]}>
        <boxGeometry args={[width * 0.95, 0.04, 0.01]} />
        <meshStandardMaterial color="#d4af37" />
      </mesh>
      {/* Back (west) */}
      <mesh position={[0, embroideryBandY, -depth / 2 - bandThickness / 2 - 0.01]}>
        <boxGeometry args={[width * 0.95, 0.04, 0.01]} />
        <meshStandardMaterial color="#d4af37" />
      </mesh>
      {/* Left (north) */}
      <mesh position={[-width / 2 - bandThickness / 2 - 0.01, embroideryBandY, 0]}>
        <boxGeometry args={[0.01, 0.04, depth * 0.95]} />
        <meshStandardMaterial color="#d4af37" />
      </mesh>
      {/* Right (south) */}
      <mesh position={[width / 2 + bandThickness / 2 + 0.01, embroideryBandY, 0]}>
        <boxGeometry args={[0.01, 0.04, depth * 0.95]} />
        <meshStandardMaterial color="#d4af37" />
      </mesh>
      {/* Door (east face, left side) */}
      <mesh position={[doorX, doorY, depth / 2 + 0.021]}>
        <boxGeometry args={[doorWidth, doorHeight, 0.03]} />
        <meshStandardMaterial color="#d4af37" />
      </mesh>
      {/* Black Stone (Hajar al-Aswad) - northeast corner, intersection of north and east walls */}
      <mesh position={[stoneX, height / 2 + stoneY, stoneZ]} rotation={[0, -Math.PI / 2, Math.PI / 8]} scale={[stoneRadiusX, stoneRadiusY, 0.09]}>
        <sphereGeometry args={[1, 32, 32]} />
        <meshStandardMaterial color="#333" />
      </mesh>
      {/* Gold ring around Black Stone (oval) */}
      <mesh position={[stoneX - 0.01, height / 2 + stoneY, stoneZ]} rotation={[0, -Math.PI / 2, Math.PI / 8]} scale={[1, stoneRadiusY / stoneRadiusX, 1]}>
        <ringGeometry args={[stoneRadiusX * 1.1, stoneRadiusX * 1.3, 32]} />
        <meshStandardMaterial color="#d4af37" side={DoubleSide} />
      </mesh>
      {/* Silver ring around Black Stone (oval) */}
      <mesh position={[stoneX - 0.01, height / 2 + stoneY, stoneZ]} rotation={[0, -Math.PI / 2, Math.PI / 8]} scale={[1, stoneRadiusY / stoneRadiusX, 1]}>
        <ringGeometry args={[stoneRadiusX * 1.05, stoneRadiusX * 1.38, 32]} />
        <meshStandardMaterial color="#c0c0c0" side={DoubleSide} />
      </mesh>
      {/* Meezab (golden spout) - on the roof, middle of the east wall, tilted downward */}
      {/* The Meezab is a golden spout on the roof of the Kaaba, used to drain rainwater. It is a significant feature, symbolizing mercy and blessings. */}
      <mesh
        position={[width / 1.8 + 0.04, height - 0.10, 0]} // Middle of east wall, slightly down from the roof, flush with wall
        rotation={[-Math.PI / 2, 0.11, 0]} // Tilted downward
       // scale={[0.1, 0.1, 0.1]} // Adjust size as needed
      >
        <boxGeometry args={[0.5, 0.18, 0.09]} />
        <meshStandardMaterial color="#d4af37" />
      </mesh>
    </group>
  );
};

export default KaabaModel;
