// Whether this browser can create a WebGL context. Checked once and cached.
//
// Some browsers have WebGL turned off (corporate policy, blocklisted GPU,
// "Use graphics acceleration" off, some headless and privacy modes). A
// three.js / react-three-fiber <Canvas> throws there, so callers check this
// first and draw a static fallback instead.
let cached;

export function isWebGLAvailable() {
    if (cached !== undefined) return cached;
    try {
        if (typeof window === 'undefined' || !window.WebGLRenderingContext) {
            cached = false;
            return cached;
        }
        const canvas = document.createElement('canvas');
        const gl =
            canvas.getContext('webgl2') ||
            canvas.getContext('webgl') ||
            canvas.getContext('experimental-webgl');
        cached = !!gl;
        // Free the probe context straight away; browsers cap live contexts.
        const lose = gl && gl.getExtension && gl.getExtension('WEBGL_lose_context');
        if (lose) lose.loseContext();
    } catch (e) {
        cached = false;
    }
    return cached;
}
