import React, { useRef } from 'react';
import { useFrame } from '@react-three/fiber';

const PILGRIM_COUNT = 24;
const RADIUS = 2.2; // Distance from Kaaba center
const HEIGHT = 0.15;

const PilgrimsModel = () => {
  const groupRef = useRef();
  // Animate pilgrims around the Kaaba
  useFrame(({ clock }) => {
    if (groupRef.current) {
      groupRef.current.rotation.y = clock.getElapsedTime() * 0.25;
    }
  });
  return (
    <group ref={groupRef}>
      {Array.from({ length: PILGRIM_COUNT }).map((_, i) => {
        const angle = (i / PILGRIM_COUNT) * Math.PI * 2;
        const x = Math.cos(angle) * RADIUS;
        const z = Math.sin(angle) * RADIUS;
        return (
          <mesh key={i} position={[x, HEIGHT, z]}>
            <sphereGeometry args={[0.09, 16, 16]} />
            <meshStandardMaterial color="#fff" />
          </mesh>
        );
      })}
    </group>
  );
};

export default PilgrimsModel;
